class Solution {
public:
    vector<int> intersect(vector<int>& nums1, vector<int>& nums2) {
        unordered_map<int, int> counts;
        for (int x : nums1) counts[x]++;
        vector<int> res;
        for (int x : nums2) {
            if (counts[x] > 0) {
                res.push_back(x);
                counts[x]--;
            }
        }
        return res;
    }
};

class Solution {
    public int[] intersect(int[] nums1, int[] nums2) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int x : nums1) counts.put(x, counts.getOrDefault(x, 0) + 1);
        List<Integer> resList = new ArrayList<>();
        for (int x : nums2) {
            int c = counts.getOrDefault(x, 0);
            if (c > 0) {
                resList.add(x);
                counts.put(x, c - 1);
            }
        }
        int[] res = new int[resList.size()];
        for (int i = 0; i < resList.size(); i++) res[i] = resList.get(i);
        return res;
    }
}

var intersect = function(nums1, nums2) {
    const counts = new Map();
    for (const x of nums1) counts.set(x, (counts.get(x) || 0) + 1);
    const res = [];
    for (const x of nums2) {
        const c = counts.get(x) || 0;
        if (c > 0) {
            res.push(x);
            counts.set(x, c - 1);
        }
    }
    return res;
};
